// QA: 战斗缩放与确定性 tick 不变量
// 不修改基座测试；模块未就绪时显式 skip。
import { test } from 'node:test';
import assert from 'node:assert/strict';

const CANDIDATES = [
  '../js/gameplay/combat.js',
  '../js/gameplay/combat.mjs',
  '../js/gameplay/battle.js',
];

async function loadCombat() {
  for (const p of CANDIDATES) {
    try { return await import(p); } catch { /* try next */ }
  }
  return null;
}

const mod = await loadCombat();
const skip = mod ? false : 'gameplay combat module not found (see open_questions)';

// 期望缩放表（产品基准）
const TABLE = {
  1: { hp: 1.0, dmg: 1.0, gold: 1.0 },
  2: { hp: 1.6, dmg: 1.15, gold: 1.25 },
  3: { hp: 2.1, dmg: 1.25, gold: 1.45 },
  4: { hp: 2.6, dmg: 1.35, gold: 1.65 },
};

function pickScaleFn(m) {
  return m.scaleForPlayers || m.getMultiplayerScale || m.multiplayerScale || null;
}

for (const n of [1, 2, 3, 4]) {
  test(`C-0${n} ${n}人缩放查表`, { skip }, () => {
    const fn = pickScaleFn(mod);
    assert.ok(typeof fn === 'function', 'scale function missing');
    const s = fn(n);
    const e = TABLE[n];
    assert.equal(s.hp, e.hp);
    assert.equal(s.dmg, e.dmg);
    assert.equal(s.gold, e.gold);
  });
}

test('C-05 Boss 额外 +10% 血量', { skip }, () => {
  const fn = mod.bossHpMultiplier || mod.getBossHpMultiplier;
  assert.ok(typeof fn === 'function', 'boss hp multiplier missing');
  assert.equal(fn(1), 1.1);
  assert.equal(fn(2), 1.6 * 1.1);
});

test('C-06 固定步长确定性', { skip }, () => {
  const tick = mod.tick || mod.step;
  assert.ok(typeof tick === 'function', 'tick missing');
  const input = { dt: 1, actions: [{ type: 'attack', power: 10 }] };
  const a = tick(structuredClone(input));
  const b = tick(structuredClone(input));
  assert.deepEqual(a, b);
});

test('C-07 伤害管线顺序', { skip }, () => {
  const fn = mod.computeDamage || mod.damagePipeline;
  assert.ok(typeof fn === 'function', 'damage pipeline missing');
  // 基础10, 词条+5, 暴击x2, 防御减免50%, 2人缩放1.15
  const d = fn({ base: 10, affix: 5, crit: true, critMul: 2, defense: 0.5, players: 2 });
  // (10+5)*2*0.5*1.15 = 17.25
  assert.ok(Math.abs(d - 17.25) < 1e-6, `got ${d}`);
});

// QA: 掉落品质权重、Boss 保底、独立分桶
import { test } from 'node:test';
import assert from 'node:assert/strict';

const CANDIDATES = [
  '../js/gameplay/loot.js',
  '../js/gameplay/loot.mjs',
  '../js/gameplay/drop.js',
];

async function loadLoot() {
  for (const p of CANDIDATES) {
    try { return await import(p); } catch { /* next */ }
  }
  return null;
}

const mod = await loadLoot();
const skip = mod ? false : 'gameplay loot module not found (see open_questions)';

const WEIGHTS = { white: 40, green: 30, blue: 20, purple: 8, orange: 2 };

function rollFn(m) {
  return m.rollQuality || m.rollDrop || m.rollLoot || null;
}

test('L-01 品质权重分布（大样本容差）', { skip }, () => {
  const roll = rollFn(mod);
  assert.ok(typeof roll === 'function', 'roll function missing');
  const N = 20000;
  const cnt = { white: 0, green: 0, blue: 0, purple: 0, orange: 0 };
  for (let i = 0; i < N; i++) cnt[roll({ boss: false })]++;
  for (const k of Object.keys(WEIGHTS)) {
    const p = cnt[k] / N;
    const e = WEIGHTS[k] / 100;
    assert.ok(Math.abs(p - e) < 0.02, `${k} got ${p.toFixed(3)} expect ${e}`);
  }
});

test('L-02 Boss 保底蓝', { skip }, () => {
  const roll = rollFn(mod);
  const order = ['white', 'green', 'blue', 'purple', 'orange'];
  for (let i = 0; i < 2000; i++) {
    const q = roll({ boss: true });
    assert.ok(order.indexOf(q) >= order.indexOf('blue'), `boss dropped ${q}`);
  }
});

test('L-03 Boss 紫/橙概率', { skip }, () => {
  const roll = rollFn(mod);
  const N = 20000;
  let purple = 0, orange = 0;
  for (let i = 0; i < N; i++) {
    const q = roll({ boss: true });
    if (q === 'purple') purple++;
    if (q === 'orange') orange++;
  }
  assert.ok(Math.abs(purple / N - 0.20) < 0.03, `purple ${purple / N}`);
  assert.ok(Math.abs(orange / N - 0.05) < 0.02, `orange ${orange / N}`);
});

test('L-04 装备独立分桶（按玩家 id 哈希）', { skip }, () => {
  const fn = mod.bucketForPlayer || mod.playerBucket || null;
  assert.ok(typeof fn === 'function', 'bucket function missing');
  const a = fn('p1');
  const b = fn('p2');
  assert.notEqual(a, b);
  assert.equal(fn('p1'), a, 'bucket must be deterministic');
});

test('L-05 金币材料共享', { skip }, () => {
  const fn = mod.isSharedDrop || mod.sharedDrop || null;
  assert.ok(typeof fn === 'function', 'shared drop fn missing');
  assert.equal(fn('gold'), true);
  assert.equal(fn('material'), true);
  assert.equal(fn('equipment'), false);
});

// QA: 房间生成不变量
import { test } from 'node:test';
import assert from 'node:assert/strict';

const CANDIDATES = [
  '../js/gameplay/roomgen.js',
  '../js/gameplay/room.js',
  '../js/gameplay/maze.js',
];

async function loadRoom() {
  for (const p of CANDIDATES) {
    try { return await import(p); } catch { /* next */ }
  }
  return null;
}

const mod = await loadRoom();
const skip = mod ? false : 'gameplay roomgen module not found (see open_questions)';

function genFn(m) {
  return m.generateFloor || m.generateRoom || m.generate || null;
}

function reachable(rooms, from, to) {
  const seen = new Set([from]);
  const q = [from];
  while (q.length) {
    const cur = q.shift();
    if (cur === to) return true;
    for (const nb of rooms[cur]?.doors || []) {
      if (!seen.has(nb)) { seen.add(nb); q.push(nb); }
    }
  }
  return false;
}

test('R-01 主路径连通（入口→Boss）', { skip }, () => {
  const gen = genFn(mod);
  assert.ok(typeof gen === 'function', 'generate fn missing');
  for (let s = 1; s <= 20; s++) {
    const f = gen({ seed: s });
    assert.ok(reachable(f.rooms, f.entrance, f.boss), `seed ${s} not connected`);
  }
});

test('R-02 每层恰 1 篝火 1 商店', { skip }, () => {
  const gen = genFn(mod);
  for (let s = 1; s <= 20; s++) {
    const f = gen({ seed: s });
    const types = Object.values(f.rooms).map(r => r.type);
    assert.equal(types.filter(t => t === 'campfire').length, 1, `seed ${s} campfire`);
    assert.equal(types.filter(t => t === 'shop').length, 1, `seed ${s} shop`);
  }
});

test('R-03 钥匙门 ≤1 且钥匙可达', { skip }, () => {
  const gen = genFn(mod);
  for (let s = 1; s <= 20; s++) {
    const f = gen({ seed: s });
    const locked = Object.values(f.rooms).filter(r => r.locked);
    assert.ok(locked.length <= 1, `seed ${s} locked doors ${locked.length}`);
    if (locked.length === 1) {
      const keyRoom = Object.entries(f.rooms).find(([, r]) => r.hasKey)?.[0];
      assert.ok(keyRoom, `seed ${s} key missing`);
      assert.ok(reachable(f.rooms, f.entrance, keyRoom), `seed ${s} key unreachable`);
    }
  }
});

test('R-04 种子可复现', { skip }, () => {
  const gen = genFn(mod);
  const a = gen({ seed: 42 });
  const b = gen({ seed: 42 });
  assert.deepEqual(a.rooms, b.rooms);
});

test('R-05 种子+已探索可恢复', { skip }, () => {
  const gen = genFn(mod);
  const restore = mod.restoreFloor || mod.restore || null;
  assert.ok(typeof restore === 'function', 'restore fn missing');
  const f = gen({ seed: 7 });
  const explored = Object.keys(f.rooms).slice(0, 3);
  const r = restore({ seed: 7, explored });
  assert.deepEqual(r.rooms, f.rooms);
  assert.deepEqual(r.explored.sort(), explored.sort());
});

test('R-06 非法参数抛错', { skip }, () => {
  const gen = genFn(mod);
  assert.throws(() => gen({ seed: -1 }));
});

// QA: SaveEnvelope 版本/CRC/双备份/迁移/异常退出回篝火
import { test } from 'node:test';
import assert from 'node:assert/strict';

const CANDIDATES = [
  '../js/gameplay/save.js',
  '../js/gameplay/save.mjs',
  '../js/gameplay/persistence.js',
];

async function loadSave() {
  for (const p of CANDIDATES) {
    try { return await import(p); } catch { /* next */ }
  }
  return null;
}

const mod = await loadSave();
const skip = mod ? false : 'gameplay save module not found (see open_questions)';

function makeEnvelope(m, data) {
  const fn = m.createEnvelope || m.wrapSave || null;
  assert.ok(typeof fn === 'function', 'createEnvelope missing');
  return fn(data);
}

test('S-01 版本号存在', { skip }, () => {
  const env = makeEnvelope(mod, { gold: 10 });
  assert.ok('version' in env, 'version missing');
  assert.equal(typeof env.version, 'number');
});

test('S-02 CRC32 校验（篡改失败）', { skip }, () => {
  const verify = mod.verifyEnvelope || mod.verify || null;
  assert.ok(typeof verify === 'function', 'verify missing');
  const env = makeEnvelope(mod, { gold: 10 });
  assert.equal(verify(env), true);
  env.data.gold = 999;
  assert.equal(verify(env), false);
});

test('S-03 双备份回退', { skip }, () => {
  const load = mod.loadWithBackup || mod.load || null;
  assert.ok(typeof load === 'function', 'load missing');
  const primary = makeEnvelope(mod, { gold: 10 });
  const backup = makeEnvelope(mod, { gold: 20 });
  primary.data.gold = 999; // 破坏主备份
  const r = load({ primary, backup });
  assert.equal(r.data.gold, 20);
});

test('S-04 迁移链', { skip }, () => {
  const migrate = mod.migrate || mod.migrateEnvelope || null;
  assert.ok(typeof migrate === 'function', 'migrate missing');
  const old = { version: 1, data: { gold: 5 } };
  const cur = migrate(old);
  assert.ok(cur.version >= 2, `migrated version ${cur.version}`);
  assert.equal(cur.data.gold, 5);
});

test('S-05 异常退出回最近篝火快照', { skip }, () => {
  const recover = mod.recoverAfterCrash || mod.recover || null;
  assert.ok(typeof recover === 'function', 'recover missing');
  const campfire = { room: 'campfire-1', gold: 30 };
  const r = recover({ lastCampfire: campfire, dirty: true });
  assert.deepEqual(r, campfire);
});
